(S/'mobile-layouts-1440.html').write_text(base+'<main class="board"><div class="eyebrow">Responsive / touch</div><h1>Alsó eszközök, alsó lap, oldalsó fa</h1><p class="intro">TERV · Select + long-press helyettesíti az Alt-ot. A natív képek: 900 × 600 és 390 × 844 px. A 44 px-es célterület az érintést szolgálja.</p><div style="display:flex;gap:38px;align-items:center;justify-content:center;margin-top:30px"><img src="../mockups/mobile-landscape.png" style="width:900px;border-radius:10px"><img src="../mockups/mobile-portrait.png" style="height:600px;border-radius:10px"></div></main></body></html>',encoding='utf-8')
(S/'status-1440.html').write_text(base+'''<main class="board"><div class="eyebrow">Status / plan-v2 §9</div><h1>Az üzenet nem tűnik el a naplóval</h1><p class="intro">TERV · Három sor, 66 px. Az utolsó log-sor mindig látható; History: 200 sor. A következő állapotminták ugyanazt a helyet használják.</p>'''+''.join('<section style="position:relative;height:120px;margin-top:18px;padding-top:4px"><h2 style="font-size:15px;margin:0">'+name+'</h2><div class="status" style="position:absolute;bottom:0;border:1px solid #ffffff24;border-radius:6px"><div class="first"><span><b>'+tool+'</b> · '+selection+'</span><span>Snap: On · Save • · 60 FPS</span></div><div class="message" style="color:'+color+'">'+message+'<span>History ▴</span></div><div class="keys">'+keys+'</div></div></section>' for name,tool,selection,message,color,keys in [('01 / Ready','Select','Prop crate1 #12 · Cell 8, 6 · Hover 9, 6 / Floor','Ready · last edit applied','#a7bdac','Drag: move · Ctrl+drag: duplicate · R: 90° · Shift+R: 15°'),('02 / Error','Dig/Fill','Cell 8, 6 / Floor',"⚠ Editor: can't fill in the cell the party stands in",'#ffb5ad','Left: Dig · Right: Fill · M: Build · Alt: temporary Select'),('03 / Preview → Rebuilding → Ready','Height','Block 4 × 3 · Floor','◷ Preview · full rebuild in 5 s','#e5b85b','Floor ↑↓ · Ceiling ↑↓ · Undo: Z / Ctrl+Z'),('04 / History drawer','Select','No selection · Map Settings','History · 200 entries · latest: Ready','#a7bdac','12:04 Ready · 12:03 Rebuilt · 12:02 Preview · 12:01 Editor: cannot fill occupied cell')])+ '</main></body></html>',encoding='utf-8')
